#!/usr/bin/env python3
"""Demo: Certified Robustness Radius"""
import random

def irv_winner(scores: dict[str, float]) -> str:
    active = dict(scores)
    while len(active) > 1:
        loser = min(active, key=lambda c: active[c])
        del active[loser]
    return next(iter(active))

def compute_elimination_gap_certificate(scores: dict[str, float]) -> float:
    active = dict(scores)
    min_gap = float('inf')
    while len(active) > 1:
        sv = sorted(active.values())
        min_gap = min(min_gap, sv[1] - sv[0])
        loser = min(active, key=lambda c: active[c])
        del active[loser]
    return min_gap

weights = {"cat": [0.8, -0.3, 0.5, 0.1], "dog": [-0.2, 0.9, -0.1, 0.4], "bird": [0.1, 0.2, -0.6, 0.7]}
biases = {"cat": 1.0, "dog": 0.5, "bird": -0.3}

def score_fn(x):
    return {c: sum(w*xi for w, xi in zip(weights[c], x)) + biases[c] for c in weights}

K = max(sum(abs(w) for w in wv) for wv in weights.values())
x0 = [1.0, 2.0, -0.5, 0.3]
scores = score_fn(x0)
gamma = compute_elimination_gap_certificate(scores)
r_star = gamma / (2 * K)

print(f"Scores: {scores}")
print(f"IRV winner: {irv_winner(scores)}")
print(f"Gap gamma={gamma:.4f}, K={K:.4f}, certified radius r*={r_star:.4f}")

random.seed(123)
n_safe = sum(1 for _ in range(1000)
             if irv_winner(score_fn([xi + random.uniform(-r_star, r_star) for xi in x0])) == irv_winner(scores))
print(f"Within r*: {n_safe}/1000 preserved (should be 1000/1000)")

#!/usr/bin/env python3
"""Demo: Tightness of the 2ε < γ Bound"""

def irv_winner(scores: dict[str, float]) -> str:
    active = dict(scores)
    while len(active) > 1:
        loser = min(active, key=lambda c: active[c])
        del active[loser]
    return next(iter(active))

scores = {"A": 0.0, "B": 3.0}
gamma = 3.0
print(f"Scores: {scores}, gap gamma = {gamma}")
print(f"Critical eps = gamma/2 = {gamma/2}")
print("Worst case: A goes up by eps, B goes down by eps")

for eps in [1.0, 1.4, 1.499, 1.5, 1.501, 2.0]:
    perturbed = {"A": eps, "B": 3.0 - eps}
    w = irv_winner(perturbed)
    print(f"  eps={eps:.3f}: perturbed={perturbed}, residual={gamma-2*eps:+.3f}, winner={w}")
